SELECT d.dept_name, CASE WHEN d.budget >= 3498000 THEN 'high' WHEN d.budget >= 698000 THEN 'mid' ELSE 'low' END AS budget_bucket, SUM(CASE WHEN e.level = 'L5' THEN e.salary ELSE 0 END) AS l5_salary FROM employees e INNER JOIN departments d ON d.id = e.dept_id GROUP BY d.dept_name, CASE WHEN d.budget >= 3498000 THEN 'high' WHEN d.budget >= 698000 THEN 'mid' ELSE 'low' END HAVING SUM(CASE WHEN e.level = 'L5' THEN e.salary ELSE 0 END) >= 59;
